// -----------------------------------------------------------------------------
// Seeder de FoodItem
// -----------------------------------------------------------------------------
// Estrategia:
//   - createMany + skipDuplicates  -> un solo INSERT ... ON CONFLICT DO NOTHING
//   - Inserta en lotes de BATCH_SIZE para no saturar la conexión
//   - name tiene @unique -> el conflict target es automático en Postgres
// -----------------------------------------------------------------------------

const BATCH_SIZE = 100;

function chunkArray<T>(arr: T[], size: number): T[][] {
  const chunks: T[][] = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
}

const prisma = new PrismaClient();

export async function SeedFood(): Promise<void> {
  console.log("Starting food item seeding...");

  // 1. Deduplicate by name in memory (the fixture has some duplicates)
  const seen = new Set<string>();
  const unique = DATA_FOOD.filter((f) => {
    const key = f.name.trim().toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  console.log(
    `  Unique items to process: ${unique.length} / ${DATA_FOOD.length} total items`,
  );

  // 2. Map to Prisma.FoodItemCreateManyInput
  const rows: Prisma.FoodItemCreateManyInput[] = unique.map((item) => ({
    createdById: null, // system food item
    name: item.name.trim(),
    baseQuantity: item.quantity,

    // Macronutrients
    calories: item.calorias,
    proteins: item.proteina,
    fats: item.grasas,
    carbohydrates: item.carbohidratosTotales,

    // Nutritional details
    humidity: item.humed,
    fiberTotal: item.fibraTotal,

    // Minerals
    phosphorus: item.fosforo,
    potassium: item.potasio,
    calcium: item.calcio,
    iron: item.hierro,
    magnesium: item.magnesio,
    zinc: item.zinc,
    copper: item.cobre,
    sodium: item.sodio,

    // Vitamins
    vitaminA: item.vitaminaA,
    thiamin: item.tiamina, // B1
    riboflavin: item.riboflavina, // B2
    niacin: item.niacina, // B3
    vitaminB6: item.vitaminaB6,
    ascorbicAcid: item.acidAscorb, // C

    isActive: true,
  }));

  // 3. Insert in batches with skipDuplicates (idempotent)
  const batches = chunkArray(rows, BATCH_SIZE);
  let totalInserted = 0;

  for (let i = 0; i < batches.length; i++) {
    const result = await prisma.foodItem.createMany({
      data: batches[i],
      skipDuplicates: true, // ON CONFLICT (name) DO NOTHING
    });
    totalInserted += result.count;
    console.log(
      `  Batch ${String(i + 1).padStart(2, "0")}/${batches.length}` +
        `  -> ${result.count} inserted (${batches[i].length} processed)`,
    );
  }

  console.log(`Seeding completed. Total new records: ${totalInserted}`);
}

// CLI direct execution
async function main() {
  try {
    await SeedFood();
  } catch (e) {
    console.error("Error during seeding:", e);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

